import {
  Sprite,
  SpriteNodeMaterial,
  Object3D,
  Vector2,
} from 'three/webgpu';
import { Node } from 'three/tsl';

/**
 * Creates a sprite node for a pricing card.
 *
 * @param {import('./types').NodeConfig} config
 * @param {import('./types').NodeContext} ctx
 * @returns {Object3D}
 */
export default function createNode(config, ctx) {
  const {
    imageUrl,
    atlasRegion,
    position,
    rotation,
    scale,
  } = config;

  // Load texture (cached)
  const texture = ctx.textureLoader.load(imageUrl);

  // Apply atlas region offset / repeat
  if (atlasRegion) {
    const { x, y, width, height } = atlasRegion;
    const imgW = texture.image.width;
    const imgH = texture.image.height;
    if (imgW && imgH) {
      texture.repeat.set(width / imgW, height / imgH);
      texture.offset.set(x / imgW, y / imgH);
      texture.needsUpdate = true;
    }
  }

  // Build sprite material
  const material = new SpriteNodeMaterial({
    map: texture,
    transparent: true,
    depthWrite: false,
  });

  // Create sprite
  const sprite = new Sprite(material);
  sprite.position.copy(position);
  sprite.rotation.set(rotation.x, rotation.y, rotation.z);
  sprite.scale.copy(scale);

  // Attach handler container
  sprite.userData.handlers = {};

  // Cleanup
  sprite.userData.cleanup = () => {
    texture.dispose();
    material.dispose();
    // No GSAP timelines to kill in this node
  };

  return sprite;
}
